module duel_game (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] initial_state,\n    input wire [3:0] k,\n    output reg [1:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] PLAY = 2'd1;\n    localparam [1:0] FINISH = 2'd2;\n    \n    // Game states\n    localparam [1:0] PLAY_TOKI = 2'd0;\n    localparam [1:0] PLAY_QUAILTY = 2'd1;\n    localparam [1:0] TOKITSUKAZE_WIN = 2'd2;\n    localparam [1:0] QUAILTY_WIN = 2'd3;\n    localparam [1:0] DRAW = 2'd1; // Shared with PLAY_QUAILTY bit[1]\n    \n    // Registers\n    reg [1:0] state;\n    reg [7:0] current_state;\n    reg [7:0] cycle_count;\n    reg [1:0] winner;\n    reg [7:0] history [0:15];\n    reg [3:0] hist_ptr;\n    reg [7:0] temp_state;\n    reg check_draw;\n    reg can_win;\n    integer i, j;\n    \n    // Maximum cycle limit\n    localparam [7:0] MAX_CYCLES = 8'd100;\n    \n    // Reset and state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all registers\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 2'd0;\n            current_state <= 8'd0;\n            cycle_count <= 8'd0;\n            winner <= 2'd0;\n            hist_ptr <= 4'd0;\n            check_draw <= 1'b0;\n            can_win <= 1'b0;\n            for (i = 0; i < 16; i = i + 1) history[i] <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;  // Clear done signal\n                    if (start) begin\n                        current_state <= initial_state;\n                        cycle_count <= 8'd0;\n                        hist_ptr <= 4'd0;\n                        history[0] <= initial_state;\n                        \n                        // Check if initial state is uniform\n                        if (initial_state == 8'h00 || initial_state == 8'hFF) begin\n                            winner <= PLAY_TOKI;\n                            state <= FINISH;\n                        end else begin\n                            state <= PLAY;\n                            can_win <= 1'b0;\n                        end\n                    end\n                end\n                \n                PLAY: begin\n                    // Check if current player can win\n                    can_win <= 1'b0;\n                    for (i = 0; i <= 8 - k; i = i + 1) begin\n                        // Check flipping to 0\n                        temp_state = current_state;\n                        for (j = 0; j < k; j = j + 1) temp_state[i+j] = 1'b0;\n                        if (temp_state == 8'h00 || temp_state == 8'hFF) can_win <= 1'b1;\n                        \n                        // Check flipping to 1\n                        temp_state = current_state;\n                        for (j = 0; j < k; j = j + 1) temp_state[i+j] = 1'b1;\n                        if (temp_state == 8'h00 || temp_state == 8'hFF) can_win <= 1'b1;\n                    end\n                    \n                    if (can_win) begin\n                        winner <= (cycle_count[0]) ? PLAY_QUAILTY : PLAY_TOKI;\n                        state <= FINISH;\n                    end else if (cycle_count >= MAX_CYCLES) begin\n                        winner <= DRAW;\n                        state <= FINISH;\n                    end else begin\n                        // Check for draw (cycle detection)\n                        check_draw <= 1'b0;\n                        for (i = 0; i < hist_ptr; i = i + 1) begin\n                            if (history[i] == current_state) check_draw <= 1'b1;\n                        end\n                        \n                        if (check_draw) begin\n                            winner <= DRAW;\n                            state <= FINISH;\n                        end else begin\n                            // Make optimal move - flip first k elements to alternating pattern\n                            temp_state = current_state;\n                            for (i = 0; i < k; i = i + 1) begin\n                                temp_state[i] = (cycle_count[0]) ? 1'b1 : 1'b0;\n                            end\n                            \n                            current_state <= temp_state;\n                            hist_ptr <= hist_ptr + 1;\n                            history[hist_ptr] <= temp_state;\n                            \n                            cycle_count <= cycle_count + 1;\n                            state <= PLAY;\n                        end\n                    end\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    case (winner)\n                        PLAY_TOKI: result <= 2'd0;   // Tokitsukaze\n                        PLAY_QUAILTY: result <= 2'd1; // Quailty\n                        DRAW: result <= 2'd2;        // Once again\n                        default: result <= 2'd0;\n                    endcase\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule